SELECT
  (CASE WHEN CAST('1' AS INTEGER) < 0 THEN NULL ELSE JSON_EXTRACT(JSON_ARRAY(10, 20, 30), '$[' || CAST('1' AS INTEGER) || ']') END) AS e,
  (CASE WHEN (SELECT CASE WHEN typeof(v) = 'real' THEN CAST(ROUND(v) AS INTEGER) ELSE CAST(v AS INTEGER) END FROM (SELECT 1.0 AS v)) < 0 THEN NULL ELSE JSON_EXTRACT(JSON_ARRAY('a', 'b'), '$[' || (SELECT CASE WHEN typeof(v) = 'real' THEN CAST(ROUND(v) AS INTEGER) ELSE CAST(v AS INTEGER) END FROM (SELECT 1.0 AS v)) || ']') END) AS f,
  (CASE WHEN CAST(5 AS INTEGER) < 0 THEN NULL ELSE JSON_EXTRACT(JSON_ARRAY(1), '$[' || CAST(5 AS INTEGER) || ']') END) AS g;